374:impl Encoder for DsaAsyncBytesEncoder {
375:    type Item = Bytes;
376:    type Error = Status;
377:
378:    #[inline]
379:    fn poll_encode(
380:        &mut self,
381:        cx: &mut Context<'_>,
382:        item: &mut Option<Self::Item>,
383:        mut dst: EncodeBuf<'_>,
384:    ) -> Poll<Result<(), Self::Error>> {
385:        if self.pending.is_some() {
386:            return self.poll_pending(cx, item, dst);
387:        }
388:
389:        let payload = item.as_ref().expect("encoder item available");
390:        let payload_len = payload.len();
391:        if !self.should_accelerate(payload_len) {
392:            let item = item.take().expect("encoder item available");
393:            dst.put(item);
394:            return Poll::Ready(Ok(()));
395:        }
396:
397:        if payload_len > u32::MAX as usize {
398:            let _encoded_item = item.take().expect("encoder item available");
399:            return Poll::Ready(Err(Status::internal(format!(
400:                "async dsa bytes encode cannot copy {payload_len} bytes; maximum DSA transfer is {} bytes",
401:                u32::MAX
402:            ))));
403:        }
404:
405:        let work_queue = self
406:            .work_queue
407:            .as_ref()
408:            .expect("DSA work queue checked before encoding")
409:            .clone();
410:        self.pending = Some(PendingCopy::dsa(work_queue, payload.clone()));
411:        self.poll_pending(cx, item, dst)
412:    }
