501:impl PendingDsaCopy {
502:    fn new(work_queue: SharedDsaWorkQueue, source: Bytes) -> Pin<Box<Self>> {
503:        Box::pin(Self {
504:            work_queue,
505:            source,
506:            dst: std::ptr::null_mut(),
507:            dst_len: 0,
508:            desc: DsaHwDesc::default(),
509:            completion: DsaCompletionRecord::default(),
510:            submitted: false,
511:            completed: false,
512:            _pin: PhantomPinned,
513:        })
514:    }
515:
516:    fn poll(
517:        mut self: Pin<&mut Self>,
518:        cx: &mut Context<'_>,
519:        mut dst: EncodeBuf<'_>,
520:    ) -> Poll<Result<(), Status>> {
521:        let this = self.as_mut().project_mut();
522:
523:        if !*this.submitted {
524:            let len = this.source.len();
525:            // SAFETY: This experiment assumes Tonic's encode buffer allocation
526:            // remains stable while `poll_encode` returns `Pending`. The pending
527:            // state stores the pointer only until completion and advances the
528:            // same reservation exactly once on success.
529:            let dst_ptr = unsafe { dst.reserve_uninit_slice_for_pending(len) };
530:            touch_pages_for_dsa(this.source.as_ptr(), dst_ptr, len);
531:
532:            this.completion.clear();
533:            this.desc
534:                .fill_memmove(this.source.as_ptr(), dst_ptr, len as u32);
535:            this.desc.set_completion(this.completion);
536:            this.work_queue.submit(this.desc);
537:            *this.dst = dst_ptr;
538:            *this.dst_len = len;
539:            *this.submitted = true;
540:        }
541:
542:        if this.completion.status() == DsaCompletionStatus::None.as_u8() {
543:            cx.waker().wake_by_ref();
544:            return Poll::Pending;
545:        }
546:
547:        *this.completed = true;
548:        match ensure_dsa_success(
549:            *this.completion,
550:            this.source.len(),
551:            &this.work_queue.config.device_path,
552:        ) {
553:            Ok(()) => {
554:                // SAFETY: DSA completion with success means the descriptor has
555:                // initialized the exact bytes in the reservation made on the
556:                // first poll. This is the single matching commit for that
557:                // reservation.
558:                unsafe {
559:                    dst.advance_reserved_uninit_slice(*this.dst_len);
560:                }
561:                Poll::Ready(Ok(()))
562:            }
563:            Err(status) => Poll::Ready(Err(status)),
564:        }
565:    }
566:
567:    fn drain_completion(&mut self) {
568:        if !self.submitted || self.completed {
569:            return;
570:        }
571:
572:        while self.completion.status() == DsaCompletionStatus::None.as_u8() {
573:            core::hint::spin_loop();
574:        }
575:        self.completed = true;
576:    }
