578:    fn project_mut(self: Pin<&mut Self>) -> PendingDsaCopyProjection<'_> {
579:        // SAFETY: `PendingDsaCopy` is pinned in a `Box`, and this method never
580:        // moves any field out of the pinned allocation. Mutable references are
581:        // used only to update descriptor/completion bytes and scalar state in
582:        // place while their addresses remain stable.
583:        let this = unsafe { self.get_unchecked_mut() };
584:        PendingDsaCopyProjection {
585:            work_queue: &this.work_queue,
586:            source: &this.source,
587:            dst: &mut this.dst,
588:            dst_len: &mut this.dst_len,
589:            desc: &mut this.desc,
590:            completion: &mut this.completion,
591:            submitted: &mut this.submitted,
592:            completed: &mut this.completed,
593:        }
594:    }
595:}
